import React, {useState, useEffect} from 'react'
import { Route, Routes} from 'react-router-dom'
import './App.css'
import HomePage from './components/homepage';


function App() {

  return (
    <div className="App">
      <Routes>
          <Route path='/' element={<HomePage/>}/>
          <Route element='/itemdetails' />
      </Routes>
    </div>
  );
}

export default App;
